import * as THREE from 'three';
import {record,recordMovement} from './analysis.js';
export function setupControls(camera,renderer){const keys={};const velocity=new THREE.Vector3();const direction=new THREE.Vector3();let yaw=0,pitch=0,locked=false,lastX=0,lastY=0,stick={x:0,y:0},lookTouch=null;const isMobile=matchMedia('(pointer: coarse)').matches||innerWidth<760;if(isMobile)document.body.classList.add('mobile');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyE')window.dispatchEvent(new Event('interact-nearest'));if(e.code==='ShiftLeft'||e.code==='ShiftRight')record('移動','走行を開始',{D:1});});
document.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('click',()=>{if(!isMobile&&!locked&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()});
document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===renderer.domElement);
document.addEventListener('mousemove',e=>{if(!locked)return;yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-1.35,1.35)});
const stickEl=document.getElementById('stick'),knob=document.getElementById('stickKnob');if(stickEl){stickEl.addEventListener('pointerdown',e=>{stickEl.setPointerCapture(e.pointerId);moveStick(e)});stickEl.addEventListener('pointermove',e=>{if(stickEl.hasPointerCapture(e.pointerId))moveStick(e)});const end=()=>{stick={x:0,y:0};knob.style.transform='translate(0px,0px)'};stickEl.addEventListener('pointerup',end);stickEl.addEventListener('pointercancel',end)}
function moveStick(e){const r=stickEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),scale=Math.min(1,42/(len||1));stick={x:dx*scale/42,y:dy*scale/42};knob.style.transform=`translate(${stick.x*35}px,${stick.y*35}px)`}
renderer.domElement.addEventListener('touchstart',e=>{for(const t of e.changedTouches)if(t.clientX>innerWidth*.45)lookTouch={id:t.identifier,x:t.clientX,y:t.clientY}},{passive:true});
renderer.domElement.addEventListener('touchmove',e=>{if(!lookTouch)return;for(const t of e.changedTouches)if(t.identifier===lookTouch.id){yaw-=(t.clientX-lookTouch.x)*.006;pitch=clamp(pitch-(t.clientY-lookTouch.y)*.004,-1.35,1.35);lookTouch.x=t.clientX;lookTouch.y=t.clientY}},{passive:true});
renderer.domElement.addEventListener('touchend',e=>{for(const t of e.changedTouches)if(lookTouch&&t.identifier===lookTouch.id)lookTouch=null},{passive:true});
document.getElementById('mobileAction').addEventListener('click',()=>window.dispatchEvent(new Event('interact-nearest')));
const forward=new THREE.Vector3();const right=new THREE.Vector3();let moved=0;
return {update(dt){const f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-stick.y;const s=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stick.x;direction.set(s,0,f);if(direction.lengthSq()>1)direction.normalize();const running=!!(keys.ShiftLeft||keys.ShiftRight);const speed=running?9:4.8;forward.set(-Math.sin(yaw),0,-Math.cos(yaw));right.set(Math.cos(yaw),0,-Math.sin(yaw));const dx=(right.x*direction.x+forward.x*direction.z)*speed*dt,dz=(right.z*direction.x+forward.z*direction.z)*speed*dt;camera.position.x=clamp(camera.position.x+dx,-7,7);camera.position.z=clamp(camera.position.z+dz,-135,14);camera.position.y=1.65;camera.rotation.order='YXZ';camera.rotation.y=yaw;camera.rotation.x=pitch;const dist=Math.hypot(dx,dz);recordMovement(dist,running);moved+=dist;if(moved>4){record('移動',running?'都市内を走行':'都市内を歩行',running?{D:1}:{S:1});moved=0}},get yaw(){return yaw},get locked(){return locked},isMobile};}
